use std::{fs,path::Path,collections::BTreeMap};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-sdk-paired-control";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn main(){let r=Path::new(R);let mut pins=BTreeMap::new();let manifest=read("/tmp/zopro-grouping-module/production-source-manifest.json");for(rel,h)in manifest["source_files_sha256"].as_object().unwrap(){let p=Path::new("/home/ubuntu/src/zk-tools/zopro").join(rel);assert_eq!(hash(&p),h.as_str().unwrap());pins.insert(p.display().to_string(),hash(p));}let a=read("/tmp/zopro-grouping-module/native/candidate/artifacts.json");for(p,h)in a["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pins.insert(p.clone(),hash(p));}assert_eq!(hash(a["binary"].as_str().unwrap()),a["binary_sha256"].as_str().unwrap());
 for p in [r.join("driver.rs"),r.join("support/perf.rs"),r.join("design.md"),r.join("setup.rs"),r.join("setup"),Path::new("/tmp/zopro-grouping-module/native/candidate/artifacts.json").to_path_buf(),Path::new("/tmp/zopro-grouping-module/native/libraries/stdout.log").to_path_buf(),Path::new("/tmp/zopro-xtask-fast-screen-target/release/xtask").to_path_buf()]{pins.insert(p.display().to_string(),hash(p));}save(r.join("build-pins.json"),&json!(pins));save(r.join("source-audit.json"),&json!({"production_sources_checked_unchanged":170,"all8accepted_libraries_exact":true,"new_driver":true,"same_historical_executable":false,"new_core_or_field_build":false,"new_arithmetic_or_schedule":false,"new_pool_or_worker_pin":false,"proof_cache":false,"candidate_compared":false,"neutral_labels_same_prove_call":true,"native_field_core_qualification_inherited":true,"adopted":false}));
 save(r.join("build-plan.json"),&json!({"version":1,"source_pins":r.join("build-pins.json"),"steps":[{"kind":"command","name":"compiler","argv":["rustc","-Vv"]},{"kind":"link-sdk","name":"control","artifacts":"/tmp/zopro-grouping-module/native/libraries/stdout.log","driver":r.join("driver.rs"),"additional_sources":[r.join("support/perf.rs")],"rustc_flags":["-O","-C","target-cpu=native","-C","lto=fat","-C","codegen-units=1"],"timeout_seconds":1200}]}));println!("Frozen new neutral diagnostic driver linked to exact8acceptedlibraries;170productionfiles unchanged");}
